BEGIN TRANSACTION;
CREATE TABLE exam_categories (
            examnumcode   INTEGER PRIMARY KEY,
            name          TEXT    NOT NULL,
            category      TEXT    NOT NULL
        );
CREATE TABLE slis_exams (
            oldexam         INTEGER,
            oldvisit        INTEGER,
            oldorder        TEXT,
            oldpers         INTEGER,
            olddiagnostis   TEXT,
            aa              INTEGER,
            extracode       INTEGER,          -- Order ID; NOT unique per exam
            visitid         INTEGER,
            demogid         INTEGER,
            fname           TEXT,
            lname           TEXT,
            examid          INTEGER,
            examnumcode     INTEGER,
            examname        TEXT,
            visitdate       TEXT,
            labcodeid       INTEGER,
            laboratoryname  TEXT,
            wardid          INTEGER,
            wcode           TEXT,
            wname           TEXT,
            diagnostis      INTEGER,
            personelid      INTEGER,
            code            TEXT,
            name            TEXT,
            notes           TEXT,
            exammoreid      INTEGER PRIMARY KEY,  -- Unique exam instance ID (TRUE PK)
            category        TEXT,
            slis_synced_at  TEXT DEFAULT NULL,
            FOREIGN KEY (examnumcode) REFERENCES exam_categories (examnumcode)
        );
CREATE INDEX idx_slis_exams_diagnostis  ON slis_exams (diagnostis);
CREATE INDEX idx_slis_exams_visitdate    ON slis_exams (visitdate);
CREATE INDEX idx_slis_exams_extracode    ON slis_exams (extracode);
CREATE INDEX idx_slis_exams_examnumcode  ON slis_exams (examnumcode);
COMMIT;
